	@Test
	void silentOptionalRetainsDiscardableConstantTrueShortcut() throws QueryEvaluationException {
		FailingFederatedService failing = new FailingFederatedService();
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(),
				serviceUrl -> failing);
		QueryValueEvaluationStep exists = strategy.precompile(
				new Exists(new LeftJoin(new SingletonSet(), service(true))),
				new QueryEvaluationContext.Minimal((Dataset) null));

		assertEquals(BooleanLiteral.TRUE, exists.evaluate(EmptyBindingSet.getInstance()));
		assertEquals(0, failing.invocationCount(), "a silent optional remains safely discardable");
	}

